#!/usr/bin/env python3
"""Validate frozen eICU model predictions on a new scored database."""

from __future__ import annotations

import argparse
import json
from pathlib import Path

import pandas as pd

from whole_body_jepa.replication import validate_scored_lockbox


def _read(path: Path) -> pd.DataFrame:
    if path.suffix.lower() == ".parquet":
        return pd.read_parquet(path)
    return pd.read_csv(path)


def main() -> None:
    parser = argparse.ArgumentParser(
        description=(
            "Evaluate predictions generated by the frozen eICU release. "
            "This command never fits or adapts on the new lockbox."
        )
    )
    parser.add_argument("--input", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument(
        "--registry",
        type=Path,
        default=Path("models/cross_database_replication_registry.json"),
    )
    parser.add_argument("--domain-column", default="domain_id")
    parser.add_argument("--time-column", default="time_block")
    parser.add_argument("--bootstrap-repetitions", type=int, default=2000)
    args = parser.parse_args()

    registry = json.loads(args.registry.read_text())
    report = validate_scored_lockbox(
        _read(args.input),
        expected_cells=registry["strict_cell_names"],
        domain_column=args.domain_column,
        time_column=args.time_column,
        bootstrap_repetitions=args.bootstrap_repetitions,
    )
    report["source_registry"] = str(args.registry)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(report, indent=2) + "\n")
    print(
        json.dumps(
            {
                "evaluated_cells": report["evaluated_cells"],
                "strict_pass_cells": len(report["strict_pass_cells"]),
                "missing_expected_cells": len(report["missing_expected_cells"]),
                "output": str(args.output),
            },
            indent=2,
        )
    )


if __name__ == "__main__":
    main()
